const d = $json.body ?? $json;
if (d.approved !== true) throw new Error('Bloqueado: aprovação explícita obrigatória.');
const content_id = String(d.content_id ?? '').trim();
const idempotency_key = String(d.idempotency_key ?? '').trim();
const caption = String(d.caption ?? '').trim();
if (!content_id || !idempotency_key || !caption) throw new Error('content_id, idempotency_key e caption são obrigatórios.');
const allowed = new Set(['linkedin','youtube','instagram','tiktok','facebook','x']);
const channels = [...new Set((Array.isArray(d.channels)?d.channels:[]).map(v=>String(v).toLowerCase()).filter(v=>allowed.has(v)))];
if (!channels.length) throw new Error('Nenhum canal válido foi informado.');
return [{json:{content_id,idempotency_key,caption,channels,approved:true,status:'queued_not_published',publish_confirmed:false,received_at:new Date().toISOString(),instruction:'Conectar um adaptador autenticado após homologar a conta e as permissões.'}}];
